    args = context.CLIARGS['args']

    if not args and not requirements_file:
        if context.CLIARGS['type'] == 'collection':
            raise AnsibleError("You must specify a collection name or a requirements file.")
        raise AnsibleOptionsError("- you must specify a user/role name or a roles file")

    if context.CLIARGS['type'] == 'collection' and args and requirements_file:
        raise AnsibleError("The positional collection_name arg and --requirements-file are mutually exclusive.")

    requirements = None
    if requirements_file:
        if context.CLIARGS['type'] == 'role' and not requirements_file.endswith(('.yaml', '.yml')):
            raise AnsibleError("Invalid role requirements file, it must end with a .yml or .yaml extension")
        requirements_file = GalaxyCLI._resolve_path(requirements_file)
        requirements = self._parse_requirements_file(
            requirements_file, allow_old_format=context.CLIARGS['type'] == 'role')

        if not requirements.get('roles') and not requirements.get('collections'):
            display.display('Skipping install, no requirements found')
            return 0

        if context.CLIARGS['type'] == 'collection' and requirements.get('roles'):
            display.display("The requirements file '%s' contains roles which will be ignored. To install these roles "
                            "run 'ansible-galaxy role install -r' or to install both at the same time run "
                            "'ansible-galaxy install -r' without a custom install path." % requirements_file)
        elif context.CLIARGS['type'] == 'role' and requirements.get('collections'):
            message = ("The requirements file '%s' contains collections which will be ignored. To install these "
                       "collections run 'ansible-galaxy collection install -r' or to install both at the same "
                       "time run 'ansible-galaxy install -r' without a custom install path." % requirements_file)
            if self._implicit_role and self._custom_roles_path:
                display.warning(message + ' Collections cannot be installed to a roles path.')
            elif not self._implicit_role:
                display.vvv(message)

    if context.CLIARGS['type'] == 'role' and (not requirements or requirements.get('roles')):
        display.display('Starting galaxy role install process')
        self._install_roles(role_file, requirements['roles'] if requirements else None)

    if (context.CLIARGS['type'] == 'collection' or
            (self._implicit_role and requirements_file and not self._custom_roles_path)) and (not requirements or requirements.get('collections')):
        display.display('Starting galaxy collection install process')
        self._install_collections(requirements_file, requirements['collections'] if requirements else None)

    return 0

def _install_collections(self, requirements_file, requirements):
    collections = context.CLIARGS['args'] if context.CLIARGS['type'] == 'collection' else []
    force = context.CLIARGS['force']
    output_path = context.CLIARGS.get('collections_path') or C.COLLECTIONS_PATHS[0]
    ignore_certs = context.CLIARGS['ignore_certs']
    ignore_errors = context.CLIARGS['ignore_errors']
    no_deps = context.CLIARGS['no_deps']
    force_deps = context.CLIARGS['force_with_deps']

    if requirements is None:
        requirements = self._require_one_of_collections_requirements(collections, requirements_file)

    output_path = GalaxyCLI._resolve_path(output_path)
    collections_path = C.COLLECTIONS_PATHS

    if len([p for p in collections_path if p.startswith(output_path)]) == 0:
        display.warning("The specified collections path '%s' is not part of the configured Ansible "
                        "collections paths '%s'. The installed collection won't be picked up in an Ansible "
                        "run." % (to_text(output_path), to_text(":".join(collections_path))))

    output_path = validate_collection_path(output_path)
    b_output_path = to_bytes(output_path, errors='surrogate_or_strict')
    if not os.path.exists(b_output_path):
        os.makedirs(b_output_path)

    install_collections(requirements, output_path, self.api_servers, (not ignore_certs), ignore_errors,
                        no_deps, force, force_deps, context.CLIARGS.get('allow_pre_release', False))

def _install_roles(self, role_file, roles_left):

    no_deps = context.CLIARGS['no_deps']
    force_deps = context.CLIARGS['force_with_deps']

    force = context.CLIARGS['force'] or force_deps

    if roles_left is None:
        roles_left = []
        # roles were specified directly, so we'll just go out grab them
        # (and their dependencies, unless the user doesn't want us to).
        for rname in context.CLIARGS['args']:
            role = RoleRequirement.role_yaml_parse(rname.strip())
            roles_left.append(GalaxyRole(self.galaxy, self.api, **role))

    # Select requested roots before dependency discovery so appended dependencies are still processed.
    if role_file and context.CLIARGS['args']:
        selected = []
        for role in roles_left:
            if role.name in context.CLIARGS['args']:
                selected.append(role)
            else:
                display.vvv('Skipping role %s' % role.name)
        roles_left = selected

    for role in roles_left:

        display.vvv('Processing role %s ' % role.name)

        # query the galaxy API for the role data

        if role.install_info is not None:
            if role.install_info['version'] != role.version or force:
                if force:
                    display.display('- changing role %s from %s to %s' %
                                    (role.name, role.install_info['version'], role.version or "unspecified"))
                    role.remove()
                else:
                    display.warning('- %s (%s) is already installed - use --force to change version to %s' %
                                    (role.name, role.install_info['version'], role.version or "unspecified"))
                    continue
            else:
                if not force:
                    display.display('- %s is already installed, skipping.' % str(role))
                    continue

        try:
            installed = role.install()
        except AnsibleError as e:
            display.warning(u"- %s was NOT installed successfully: %s " % (role.name, to_text(e)))
            self.exit_without_ignore()
            continue

        # install dependencies, if we want them
        if not no_deps and installed:
            if not role.metadata:
                display.warning("Meta file %s is empty. Skipping dependencies." % role.path)
            else:
                role_dependencies = (role.metadata.get('dependencies') or []) + role.requirements
                for dep in role_dependencies:
                    display.debug('Installing dep %s' % dep)
                    dep_req = RoleRequirement()
                    dep_info = dep_req.role_yaml_parse(dep)
                    dep_role = GalaxyRole(self.galaxy, self.api, **dep_info)
                    if '.' not in dep_role.name and '.' not in dep_role.src and dep_role.scm is None:
                        # we know we can skip this, as it's not going to
                        # be found on galaxy.ansible.com
                        continue
                    if dep_role.install_info is None:
                        if dep_role not in roles_left:
                            display.display('- adding dependency: %s' % to_text(dep_role))
                            roles_left.append(dep_role)
                        else:
                            display.display('- dependency %s already pending installation.' % dep_role.name)
                    else:
                        if dep_role.install_info['version'] != dep_role.version:
                            if force_deps:
                                display.display('- changing dependant role %s from %s to %s' %
                                                (dep_role.name, dep_role.install_info['version'], dep_role.version or "unspecified"))
                                dep_role.remove()
                                roles_left.append(dep_role)
                            else:
                                display.warning('- dependency %s (%s) from role %s differs from already installed version (%s), skipping' %
                                                (to_text(dep_role), dep_role.version, role.name, dep_role.install_info['version']))
                        else:
                            if force_deps:
                                roles_left.append(dep_role)
                            else:
                                display.display('- dependency %s is already installed, skipping.' % dep_role.name)

        if not installed:
            display.warning("- %s was NOT installed successfully." % role.name)
            self.exit_without_ignore()

